var TEXT = ['一元二次方程求根公式','1x²','− 4x','+ 4','= 0','a = 1','b = −4','c = 4','求根公式','x =','−b ± √(b² − 4ac)','2a','判别式','Δ = b² − 4ac','Δ = (−4)² − 4·1·4 = 16 − 16 = 0','Δ = 0'];
function charWidth(ch, size) { var code = ch.charCodeAt(0); if (code > 0x2E80) return size; if (ch === '²' || ch === '·' || ch === '±' || ch === '√' || ch === 'Δ' || ch === '−') return size * 0.65; return size * 0.6; }
function textWidth(s, size) { var w = 0; for (var i = 0; i < s.length; i++) { w += charWidth(s.charAt(i), size); } return w; }
var visual = {
  prepare: function (input) { var out = []; for (var i = 0; i < TEXT.length; i++) { out.push({ kind: 'text', payload: TEXT[i] }); } return out; },
  render: function (input, metrics) {
    var COLORS = { ink: '#1f2937', a: '#1f6feb', b: '#d9480f', c: '#2f9e44', purple: '#7b2cbf', red: '#b42318' };
    var W = (input.viewport && input.viewport.widthDu) || 720;
    var H = (input.viewport && input.viewport.heightDu) || 600;
    var scale = Math.min(W / 720, H / 600);
    var ox = (W - 720 * scale) / 2;
    var oy = (H - 600 * scale) / 2;
    function X(x) { return ox + x * scale; }
    function Y(y) { return oy + y * scale; }
    function S(v) { return v * scale; }
    var paths = [];
    var children = [];
    function addPath(id, commands, style) {
      paths.push({ id: id, commands: commands });
      var node = { type: 'path', pathId: id };
      for (var k in style) { if (style.hasOwnProperty(k)) { node[k] = style[k]; } }
      children.push(node);
    }
    function addLabel(cx, y, text, size, fill, weight, family) {
      var w = textWidth(text, size);
      var node = { type: 'label', x: X(cx - w / 2), y: Y(y), text: text, fontSize: S(size), fill: fill, fontFamily: family || 'sans-serif' };
      if (weight) { node.fontWeight = weight; }
      children.push(node);
    }
    function addLabelLeft(x, y, text, size, fill, weight, family) {
      var node = { type: 'label', x: X(x), y: Y(y), text: text, fontSize: S(size), fill: fill, fontFamily: family || 'sans-serif' };
      if (weight) { node.fontWeight = weight; }
      children.push(node);
    }
    addPath('bg', visualSdk.polyline([[0, 0], [W, 0], [W, H], [0, H], [0, 0]]), { fill: '#ffffff', stroke: 'none' });
    addPath('leader-a', visualSdk.polyline([[X(265), Y(145)], [X(265), Y(185)]]), { stroke: COLORS.a, strokeWidth: S(2), fill: 'none' });
    addPath('dot-a', visualSdk.circle(X(265), Y(142), S(4)), { fill: COLORS.a, stroke: 'none' });
    addPath('leader-b', visualSdk.polyline([[X(355), Y(145)], [X(355), Y(185)]]), { stroke: COLORS.b, strokeWidth: S(2), fill: 'none' });
    addPath('dot-b', visualSdk.circle(X(355), Y(142), S(4)), { fill: COLORS.b, stroke: 'none' });
    addPath('leader-c', visualSdk.polyline([[X(435), Y(145)], [X(435), Y(185)]]), { stroke: COLORS.c, strokeWidth: S(2), fill: 'none' });
    addPath('dot-c', visualSdk.circle(X(435), Y(142), S(4)), { fill: COLORS.c, stroke: 'none' });
    addPath('frac-bar', visualSdk.polyline([[X(240), Y(288)], [X(560), Y(288)]]), { stroke: COLORS.ink, strokeWidth: S(2), fill: 'none' });
    var boxText = 'Δ = 0';
    var bw = textWidth(boxText, 30) + 28;
    var bh = 44;
    var bx = 360 - bw / 2;
    var by = 486;
    addPath('delta-box', visualSdk.polyline([[X(bx), Y(by)], [X(bx + bw), Y(by)], [X(bx + bw), Y(by + bh)], [X(bx), Y(by + bh)], [X(bx), Y(by)]]), { stroke: COLORS.red, strokeWidth: S(2), fill: '#fff5f5' });
    addLabel(360, 42, '一元二次方程求根公式', 24, COLORS.ink, 'bold', 'sans-serif');
    addLabel(265, 125, '1x²', 34, COLORS.ink, 'normal', 'monospace');
    addLabel(355, 125, '− 4x', 34, COLORS.ink, 'normal', 'monospace');
    addLabel(435, 125, '+ 4', 34, COLORS.ink, 'normal', 'monospace');
    addLabel(505, 125, '= 0', 34, COLORS.ink, 'normal', 'monospace');
    addLabel(265, 205, 'a = 1', 22, COLORS.a, 'bold', 'monospace');
    addLabel(355, 205, 'b = −4', 22, COLORS.b, 'bold', 'monospace');
    addLabel(435, 205, 'c = 4', 22, COLORS.c, 'bold', 'monospace');
    addLabelLeft(80, 250, '求根公式', 20, COLORS.ink, 'bold', 'sans-serif');
    addLabel(190, 295, 'x =', 32, COLORS.ink, 'normal', 'monospace');
    addLabel(400, 275, '−b ± √(b² − 4ac)', 28, COLORS.ink, 'normal', 'monospace');
    addLabel(400, 320, '2a', 28, COLORS.ink, 'normal', 'monospace');
    addLabelLeft(80, 380, '判别式', 20, COLORS.purple, 'bold', 'sans-serif');
    addLabel(360, 415, 'Δ = b² − 4ac', 30, COLORS.purple, 'normal', 'monospace');
    addLabel(360, 455, 'Δ = (−4)² − 4·1·4 = 16 − 16 = 0', 24, COLORS.ink, 'normal', 'monospace');
    addLabel(360, 516, 'Δ = 0', 30, COLORS.red, 'bold', 'monospace');
    return {
      schemaVersion: 1,
      sceneId: 'quadratic-formula-transcription',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: { type: 'group', children: children }
    };
  }
};
